  def(2, 'AD (Active Directory)', 'Microsoft-ის დირექტორიის სერვისი — ცენტრალიზებული ბაზა, რომელიც ინახავს ინფორმაციას ქსელის ობიექტებზე (მომხმარებლები, კომპიუტერები, ჯგუფები, პრინტერები) და უზრუნველყოფს აუთენტიფიკაციას და ცენტრალიზებულ მართვას.');
  def(2, 'DNS', 'Domain Name System — სისტემა, რომელიც დომენურ სახელებს (მაგ. google.com) თარგმნის IP მისამართებად და პირიქით.');
  def(2, 'OU', 'Organizational Unit — ორგანიზაციული ერთეული; კონტეინერი დომენის შიგნით, რომელშიც ალაგებ ობიექტებს (მომხმარებლები, კომპიუტერები, ჯგუფები) და რომელზეც შეგიძლია GPO-ს მიბმა და მართვის დელეგირება.');
  def(2, 'DC', 'Domain Controller — სერვერი, რომელზეც დაყენებულია AD DS; ინახავს AD-ის ბაზის ასლს და ამოწმებს მომხმარებლებს სისტემაში შესვლისას (აუთენტიფიკაცია).');
  def(2, 'LDAP', 'Lightweight Directory Access Protocol — პროტოკოლი, რომლითაც დირექტორიის (AD) მონაცემებს ეძებ, კითხულობ და ცვლი. იყენებს პორტ 389-ს.');
  def(2, 'Child Domain', 'შვილობილი დომენი — არსებული (მშობელი) დომენის ქვეშ შექმნილი დომენი, რომელიც მის სახელს აგრძელებს, მაგ. sales.company.com (მშობელი: company.com).');
  def(2, 'Member server', 'სერვერი, რომელიც დომენის წევრია, მაგრამ არ არის დომენის კონტროლერი; ასრულებს სხვა როლებს (ფაილ, ვებ, ბეჭდვის სერვერი და ა.შ.).');
  def(2, 'დომენი', 'კომპიუტერების, მომხმარებლების და რესურსების ლოგიკური ჯგუფი, რომელსაც აქვს საერთო AD ბაზა და ცენტრალიზებულად იმართება დომენის კონტროლერით.');
  def(2, 'ხე (Tree)', 'ერთი ან მეტი დომენი, რომლებიც იზიარებენ უწყვეტ (საერთო) სახელთა სივრცეს, მაგ. company.com და მისი შვილობილი sales.company.com.');
  def(2, 'ტყე (Forest)', 'AD-ის ყველაზე მაღალი დონე — ერთი ან მეტი ხე, რომლებსაც აქვთ საერთო სქემა და გლობალური კატალოგი და ერთმანეთს ენდობიან (trust).');
  def(2, 'სამუშაო ჯგუფი (Workgroup)', 'P2P ქსელი, სადაც ყველა კომპიუტერი თანასწორია, არ არის ცენტრალური სერვერი და თითოეულს აქვს საკუთარი ლოკალური ანგარიშები. პატარა ქსელებისთვისაა.');
  def(2, 'Namespace', 'სახელთა სივრცე — არე, რომელშიც ყველა სახელი უნიკალურია და ერთი სახელი ერთ ობიექტს შეესაბამება (მაგ. DNS-ის იერარქიული სახელები: company.com).');
  def(2, 'Site', 'საიტი — AD-ში ფიზიკური მდებარეობა: ერთი ან მეტი სწრაფი კავშირით დაკავშირებული IP ქვექსელი. გამოიყენება რეპლიკაციის და შესვლის ტრაფიკის სამართავად.');
  def(2, 'Hostname', 'კომპიუტერის სახელი ქსელში (მაგ. SERVER01); დომენთან ერთად ქმნის სრულ სახელს — FQDN-ს: server01.company.com.');
  def(2, 'WINS', 'Windows Internet Name Service — Microsoft-ის სერვისი, რომელიც NetBIOS სახელებს IP მისამართებად თარგმნის (როგორც DNS, ოღონდ NetBIOS-ისთვის). ძველი ტექნოლოგიაა.');
  def(2, 'GUID', 'Globally Unique Identifier — 128-ბიტიანი უნიკალური იდენტიფიკატორი, რომელიც ყოველ AD ობიექტს შექმნისას ენიჭება და არასდროს იცვლება (სახელის შეცვლის ან გადატანის შემდეგაც).');
  def(2, 'GPO', 'Group Policy Object — პარამეტრების ნაკრები, რომლითაც ცენტრალიზებულად აკონფიგურირებ მომხმარებლებს და კომპიუტერებს (პაროლის წესები, აკრძალვები, პროგრამების დაყენება). ებმება საიტს, დომენს ან OU-ს.');
  def(2, 'Hypervisor', 'პროგრამული ფენა, რომელიც ქმნის და მართავს ვირტუალურ მანქანებს და მათ შორის ანაწილებს ფიზიკურ რესურსებს (CPU, RAM, დისკი). მაგ. Hyper-V, VMware ESXi.');
  def(2, 'VMBus', 'Hyper-V-ის სწრაფი შიდა საკომუნიკაციო არხი ჰოსტს (parent partition) და ვირტუალურ მანქანებს (child partitions) შორის; მისით მუშაობს ვირტუალური მოწყობილობები.');
  def(2, 'Snapshot', 'ვირტუალური მანქანის მდგომარეობის „ფოტო" კონკრეტულ მომენტში (დისკი, მეხსიერება, პარამეტრები), რომ საჭიროებისას ამ მომენტზე დაბრუნდე. Hyper-V-ში ჰქვია Checkpoint.');
  def(2, 'Nested Virtualization', 'ვირტუალიზაცია ვირტუალიზაციაში — ვირტუალურ მანქანაში Hyper-V-ის დაყენება და მის შიგნით სხვა ვირტუალური მანქანების გაშვება.');
  def(2, '.vhdx', 'Hyper-V-ის ვირტუალური მყარი დისკის ახალი ფორმატი; მხარს უჭერს 64 TB-მდე ზომას (ძველი .vhd — მხოლოდ 2 TB) და უფრო მდგრადია დაზიანების მიმართ.');

  open(2, 'რა არის Active Directory?', `Active Directory (AD) — Microsoft-ის დირექტორიის სერვისი Windows Server-ში.
ის ერთ ცენტრალიზებულ ბაზაში ინახავს ქსელის ყველა ობიექტს (მომხმარებლები, კომპიუტერები, ჯგუფები, პრინტერები) და ადმინისტრატორს აძლევს საშუალებას ყველაფერი ერთი ადგილიდან მართოს.
- **აუთენტიფიკაცია** — ვინ ხარ (შესვლა)
- **ავტორიზაცია** — რა გაქვს უფლება
- **ცენტრალიზებული მართვა** და Group Policy
როლის სახელი: AD DS (Active Directory Domain Services).`);
  open(2, 'რა არის AD-ს ტიპური ობიექტები?', `- მომხმარებლები (Users)
- კომპიუტერები (Computers)
- ჯგუფები (Groups)
- ორგანიზაციული ერთეულები (OU)
- პრინტერები (Printers)
- გაზიარებული საქაღალდეები (Shared folders)
- კონტაქტები (Contacts)`);
  open(2, 'რა პროტოკოლებსა და სერვისებს იყენებს AD?', `- **DNS** — დომენის კონტროლერების და კომპიუტერების პოვნა სახელით
- **LDAP** — დირექტორიაში მონაცემების ძებნა/წაკითხვა/შეცვლა
- **Kerberos** — მომხმარებლების აუთენტიფიკაცია (ძველი — NTLM)
- **DHCP** — კლიენტებისთვის IP მისამართების მინიჭება
- რეპლიკაციისთვის — RPC/SMB`);
  open(2, 'რა განსხვავებაა სამუშაო ჯგუფსა და დომენს შორის?', `- **სამუშაო ჯგუფი (Workgroup)** — P2P ქსელი: ყველა კომპიუტერი თანასწორია, არ არის ცენტრალური სერვერი, თითოეულ კომპიუტერს თავისი ლოკალური ანგარიშები აქვს. პატარა ქსელებისთვისაა (≈10–20 კომპიუტერი).
- **დომენი (Domain)** — Client-Server ქსელი: ანგარიშები და პარამეტრები ცენტრალიზებულად ინახება დომენის კონტროლერზე (AD), ერთი ანგარიშით შეგიძლია ნებისმიერ კომპიუტერზე შესვლა, იმართება Group Policy-ით. დიდი ქსელებისთვისაა.`);
  open(2, 'რა ფუნქციონალური დონეები (functional levels) არსებობს და რა სხვაობაა მათ შორის?', `ფუნქციონალური დონე განსაზღვრავს, AD-ის **რომელი შესაძლებლობები** არის ხელმისაწვდომი და Windows Server-ის **რომელი ყველაზე ძველი ვერსია** შეიძლება იყოს დომენის კონტროლერზე.
- **Domain functional level** — ეხება ერთ დომენს
- **Forest functional level** — ეხება მთელ ტყეს (ვერ იქნება დომენის დონეზე მაღალი)
დონეები: Windows Server 2008, 2008 R2, 2012, 2012 R2, 2016 (Windows Server 2019-ს ახალი დონე არ აქვს — უმაღლესია 2016).
რაც მაღალია დონე → მეტი ფუნქცია, მაგრამ ყველა DC უნდა იყოს მინიმუმ ამ ვერსიის.`);
  open(2, 'რა არის replication topology?', `რეპლიკაციის ტოპოლოგია — „რუკა", რომელიც განსაზღვრავს, **რომელი დომენის კონტროლერები ვის უზიარებენ AD-ის ცვლილებებს** და რა კავშირებით.
ავტომატურად ქმნის **KCC** (Knowledge Consistency Checker).
- **საიტის შიგნით (intra-site)** — სწრაფი, რგოლური (ring) ტოპოლოგია, ცვლილება ვრცელდება წამებში
- **საიტებს შორის (inter-site)** — site link-ებით, განრიგით (ნაგულისხმევად 180 წუთში ერთხელ), შეკუმშული მონაცემებით`);
  open(2, 'რა სხვაობაა hosts და lmhosts ფაილებს შორის?', `ორივე ლოკალური ტექსტური ფაილია (C:\\Windows\\System32\\drivers\\etc).
- **hosts** — ჰოსტის სახელებს (DNS სახელებს) უთავსებს IP მისამართებს → გამოიყენება DNS/hostname რეზოლუციისთვის
- **lmhosts** — NetBIOS სახელებს უთავსებს IP მისამართებს → გამოიყენება NetBIOS რეზოლუციისთვის (ლოკალური WINS-ის მსგავსად)`);
  open(2, 'როგორია DNS რეზოლუცია?', `სახელის (მაგ. www.google.com) IP მისამართად თარგმნის პროცესი:
1. კომპიუტერი ამოწმებს თავის **DNS ქეშს** და **hosts** ფაილს
2. თუ არ არის — ეკითხება თავის **DNS სერვერს** (რეკურსიული მოთხოვნა)
3. სერვერი თუ არ იცის — ეკითხება **root სერვერს → TLD სერვერს (.com) → დომენის ავტორიტეტულ სერვერს**
4. IP მისამართი უბრუნდება კლიენტს და ორივე მხარე მას ქეშში ინახავს`);
  open(2, 'როგორია NetBIOS რეზოლუცია?', `NetBIOS სახელის (15 სიმბოლომდე) IP მისამართად თარგმნა. თანმიმდევრობა:
1. **NetBIOS ქეში**
2. **WINS სერვერი**
3. **Broadcast** (ქსელში „ყვირილი")
4. **lmhosts** ფაილი
5. ბოლოს — **hosts** ფაილი და **DNS**
(ზუსტი რიგი დამოკიდებულია node type-ზე: B, P, M, H-node.)`);
  open(2, 'რა DNS zones არსებობს და რა სხვაობაა მათ შორის?', `- **Primary zone** — მთავარი ზონა, ჩაწერა-წაკითხვის (read/write) ასლი
- **Secondary zone** — მხოლოდ წასაკითხი ასლი, რომელიც primary-დან zone transfer-ით მოდის
- **Stub zone** — შეიცავს მხოლოდ NS, SOA და glue A ჩანაწერებს — „იცის", რომელი სერვერია ავტორიტეტული
- **AD-integrated zone** — ინახება AD-ში და AD-სთან ერთად რეპლიცირდება (უსაფრთხო დინამიური განახლება)
მიმართულების მიხედვით: **Forward lookup** (სახელი → IP) და **Reverse lookup** (IP → სახელი).`);
  open(2, 'რას აკეთებს WINS server?', `WINS სერვერი **NetBIOS სახელებს თარგმნის IP მისამართებად**.
კლიენტები თავიანთ NetBIOS სახელს და IP-ს დინამიურად არეგისტრირებენ WINS-ის ბაზაში, სხვები კი იქიდან იგებენ მისამართებს. ასე მცირდება broadcast ტრაფიკი. ძველი ტექნოლოგიაა — დღეს ძირითადად DNS გამოიყენება.`);
  open(2, 'რას წარმოადგენს Users კონტეინერი?', `Users — AD-ის **ნაგულისხმევი კონტეინერი** (CN=Users), რომელიც დომენის შექმნისას ავტომატურად იქმნება.
შეიცავს ჩაშენებულ მომხმარებლებს (Administrator, Guest) და ჯგუფებს (Domain Admins, Domain Users და სხვ.).
მნიშვნელოვანია: ეს **კონტეინერია და არა OU** — მასზე პირდაპირ GPO-ს ვერ მიაბამ და შიგნით OU-ს ვერ შექმნი.`);
  open(2, 'რა ჯგუფები გამოიყოფა ჯგუფის ტიპის მიხედვით და რა სხვაობაა მათში?', `- **Security groups (უსაფრთხოების ჯგუფები)** — გამოიყენება უფლებების და ნებართვების მისანიჭებლად რესურსებზე (შეიძლება ელ-ფოსტისთვისაც)
- **Distribution groups (გავრცელების ჯგუფები)** — მხოლოდ ელ-ფოსტის სიებისთვის (მაგ. Exchange); მათით ნებართვებს **ვერ** მიანიჭებ`);
  open(2, 'რა ჯგუფები გამოიყოფა ჯგუფის სკოუპის (scope) მიხედვით და რა სხვაობაა მათში?', `- **Domain Local** — ნებართვები ეძლევა **იმავე დომენის** რესურსებზე; წევრები შეიძლება იყვნენ ნებისმიერი დომენიდან
- **Global** — წევრები მხოლოდ **იმავე დომენიდან**; შეიძლება მიეცეს წვდომა ტყის ნებისმიერი დომენის რესურსებზე (მომხმარებლების დაჯგუფება როლით/განყოფილებით)
- **Universal** — წევრები **ტყის ნებისმიერი დომენიდან**, წვდომა ნებისმიერ დომენში; ინახება Global Catalog-ში`);
  open(2, 'რა არის AGDLP / AGUDLP?', `Microsoft-ის რეკომენდებული წესი ჯგუფების და ნებართვების სწორად გამოსაყენებლად:
- **AGDLP** — **A**ccounts → **G**lobal groups → **D**omain **L**ocal groups → **P**ermissions
- **AGUDLP** — **A**ccounts → **G**lobal → **U**niversal → **D**omain **L**ocal → **P**ermissions (რამდენიმე დომენიანი ტყისთვის)
ანუ: მომხმარებლებს სვამ გლობალურ ჯგუფში → გლობალურ ჯგუფს სვამ Domain Local ჯგუფში → ნებართვას აძლევ Domain Local ჯგუფს.`);
  open(2, 'რა განსხვავებაა Type 1 და Type 2 ჰიპერვიზორებს შორის და რომელ ტიპს განეკუთვნება Microsoft Hyper-V?', `- **Type 1 (bare-metal)** — პირდაპირ აპარატურაზე მუშაობს, OS-ის გარეშე; სწრაფი და უსაფრთხო (Hyper-V, VMware ESXi, Xen)
- **Type 2 (hosted)** — მუშაობს როგორც პროგრამა არსებულ OS-ზე; ნელი, სატესტოდ (VirtualBox, VMware Workstation)
**Hyper-V არის Type 1** — Windows-ში როლად ყენდება, მაგრამ ინსტალაციის შემდეგ ჰიპერვიზორი პირდაპირ აპარატურაზე მუშაობს, Windows კი ხდება „მშობელი პარტიცია" (parent partition).`);
  open(2, 'რა ძირითადი განსხვავებაა Generation 1 და Generation 2 ვირტუალურ მანქანებს შორის Hyper-V-ში?', `- **Generation 1** — ძველი **BIOS**, ჩატვირთვა IDE დისკიდან, მხარს უჭერს 32 და 64-ბიტიან OS-ს, ემულირებული (legacy) მოწყობილობები
- **Generation 2** — **UEFI** ფირმვერი **Secure Boot**-ით, ჩატვირთვა SCSI დისკიდან ან ქსელიდან (PXE), მხოლოდ 64-ბიტიანი OS, უფრო სწრაფი ჩატვირთვა, ნაკლები ემულირებული მოწყობილობა
ვირტუალური მანქანის შექმნის შემდეგ თაობას ვეღარ შეცვლი.`);
  open(2, 'ჩამოთვალეთ Hyper-V-ის სამი ტიპის ვირტუალური კომუტატორი (switch).', `- **External** — ვირტუალურ მანქანებს აკავშირებს ფიზიკურ ქსელთან (ფიზიკური ქსელის ბარათით)
- **Internal** — კავშირი ვირტუალურ მანქანებს შორის და ჰოსტთან, ფიზიკური ქსელის გარეშე
- **Private** — კავშირი მხოლოდ ვირტუალურ მანქანებს შორის (ჰოსტთანაც კი არა)`);
  open(2, 'რა განსხვავებაა Standard checkpoints-სა და Production checkpoints-ს შორის?', `- **Standard checkpoint** — ინახავს ვირტუალური მანქანის სრულ მდგომარეობას, **მეხსიერების (RAM) და გაშვებული პროგრამების ჩათვლით**. კარგია ტესტირებისთვის, მაგრამ აპლიკაციების მონაცემები შეიძლება შეუთანხმებელი იყოს.
- **Production checkpoint** — ვირტუალური მანქანის შიგნით იყენებს **VSS**-ს (Windows) ან ფაილური სისტემის „გაყინვას" (Linux), რომ მონაცემები მთლიანი იყოს; **მეხსიერებას არ ინახავს**. ნაგულისხმევია და რეალური (production) გარემოსთვის რეკომენდებული.`);
  open(2, 'რა აპარატურული და პროცესორული მოთხოვნები უნდა დაკმაყოფილდეს Hyper-V როლის დასაყენებლად?', `- **64-ბიტიანი პროცესორი SLAT-ით** (Second Level Address Translation)
- **აპარატურული ვირტუალიზაცია** — Intel VT-x ან AMD-V (ჩართული BIOS/UEFI-ში)
- **აპარატურული DEP** — Intel XD bit ან AMD NX bit (ჩართული)
- **VM Monitor Mode Extensions**
- მინიმუმ **4 GB RAM** (რაც მეტი, მით უკეთესი)
- 64-ბიტიანი Windows Server ან Windows 10 Pro/Enterprise`);

  mcq(2, 'რა არის Active Directory?', ['ვებ ბრაუზერი', 'ქსელში ობიექტების შესახებ ინფორმაციის შესანახად განკუთვნილი მონაცემთა ბაზა', 'ელ-ფოსტის სერვერი', 'ვიდეო კონფერენციის ინსტრუმენტი'], 1);
