  mcq(2, 'რა არის დომენის კონტროლერის დანიშნულება Active Directory-ში?', ['პრინტერების მართვა', 'მომხმარებლის ანგარიშებისა და ნებართვების მართვა', 'ინტერნეტით წვდომის უზრუნველყოფა', 'პროგრამული განახლებების მართვა'], 1);
  mcq(2, 'რომელი ინსტრუმენტი გამოიყენება Windows Server 2019-ში Active Directory-ის სამართავად?', ['Active Directory Users and Computers', 'Microsoft Word', 'Notepad', 'Windows Media Player'], 0);
  mcq(2, 'რა არის ნაგულისხმევი რეპლიკაციის ინტერვალი Active Directory რეპლიკაციისთვის?', ['1 საათი', '6 საათი', '12 საათი', '24 საათი'], 0, 'ვარიანტებიდან სწორია 1 საათი (საიტის შიგნით კავშირის ნაგულისხმევი განრიგი). დამატებით: საიტებს შორის ნაგულისხმევია 180 წუთი.');
  mcq(2, 'რა არის გლობალური კატალოგის მიზანი Active Directory-ში?', ['ტყეში არსებული ყველა ობიექტის შესახებ ინფორმაციის შენახვა', 'ინფორმაციის შენახვა დომენის ყველა ობიექტის შესახებ', 'ორგანიზაციის ყველა მომხმარებლის შესახებ ინფორმაციის შენახვა', 'ჯგუფის პოლიტიკის შესახებ ინფორმაციის შენახვა'], 0, 'გლობალური კატალოგი ინახავს მთელი ტყის ყველა ობიექტის ნაწილობრივ (ყველაზე საჭირო ატრიბუტების) ასლს, რომ ძებნა სწრაფი იყოს.');
  mcq(2, 'ჩამოთვლილთაგან რომელი არ არის მოქმედი Active Directory-ის ორგანიზაციული ერთეული (OU)?', ['მომხმარებლები', 'კომპიუტერები', 'პრინტერები', 'ჯგუფები'], 2, 'სადავო კითხვაა. მოსალოდნელი პასუხია „პრინტერები". (ტექნიკურად Users და Computers ნაგულისხმევი კონტეინერებია და არა OU.)');
  mcq(2, 'რომელი ბრძანება გამოიყენება Windows სერვერის დომენის კონტროლერად დასაწინაურებლად (promote)?', ['dcpromo', 'promote', 'adconnect', 'dcsetup'], 0, 'dcpromo ძველი ბრძანებაა; Windows Server 2012-დან ამას Server Manager-ით ან PowerShell-ით (Install-ADDSDomainController) აკეთებენ.');
  mcq(2, 'რა არის Active Directory სქემის მიზანი?', ['Active Directory მონაცემთა ბაზის სტრუქტურის განსაზღვრა', 'მომხმარებლის პაროლების შენახვა', 'პრინტერის კონფიგურაციების მართვა', 'ელ-ფოსტის მისამართების შენახვა'], 0, 'სქემა განსაზღვრავს, რა ტიპის ობიექტები და რა ატრიბუტები შეიძლება არსებობდეს AD-ში.');
  mcq(2, 'რა არის DNS?', ['Dynamic Network Service', 'Distributed Name Server', 'Domain Name System', 'Data Network Security'], 2);
