  mcq(3, 'რომელი პროტოკოლი და პორტი გამოიყენება ვებ-სერვერთან დაშიფრული/უსაფრთხო კომუნიკაციისთვის SSL/TLS სერტიფიკატების გამოყენებით?', ['HTTP (პორტი 80)', 'FTP (პორტი 21)', 'HTTPS (პორტი 443)', 'SSH (პორტი 22)'], 2);
  mcq(3, 'IIS-ში რას წარმოადგენს „ვირტუალური დირექტორია" (Virtual Directory)?', ['ფიზიკური მყარი დისკის დაყოფას რამდენიმე ნაწილად', 'URL მისამართის კატალოგის სახელის დაკავშირებას ფაილური სისტემის კონკრეტულ საქაღალდესთან, სადაც ვებ-აპლიკაციაა განთავსებული', 'ვირტუალურ მანქანას, სადაც მხოლოდ ბრაუზერია ჩაწერილი', 'ფაილების გაზიარებულ ქსელურ რესურსს SMB პროტოკოლით'], 1);
  mcq(3, 'ზოგადად, რას წარმოადგენს აპლიკაციათა სერვერი (Application Server) IT ინფრასტრუქტურაში?', ['სერვერს, რომელიც მხოლოდ ფაილების შენახვაზეა პასუხისმგებელი', 'სერვერს, რომელიც ქსელში მომხმარებლებისთვის უზრუნველყოფს სერვისებსა და ბიზნეს-ლოგიკის აპლიკაციებს', 'მოწყობილობას, რომელიც მხოლოდ IP მისამართებს არიგებს', 'ქსელის როუტერს'], 1);
  mcq(3, 'რომელი პროტოკოლი გამოიყენება ფოსტის კლიენტის მიერ მეილ სერვერიდან წერილების ლოკალურ კომპიუტერზე ჩამოსატვირთად (პორტი 110)?', ['SMTP', 'POP3', 'DNS', 'DHCP'], 1);

  /* ════════════════════════ ქვიზი 4 ════════════════════════ */

  open(4, 'რა არის პრინტ სერვერის ფუნქცია?', `პრინტ სერვერი ქსელში **ცენტრალიზებულად მართავს პრინტერებს**:
- იღებს ბეჭდვის დავალებებს კლიენტებისგან
- აყენებს მათ რიგში (spooling) და გზავნის პრინტერზე
- კლიენტებს ავტომატურად აწვდის დრაივერებს
- აკონტროლებს, ვის აქვს ბეჭდვის უფლება
Windows Server-ში ამისთვის ყენდება **Print and Document Services (PDS)** როლი.`);
  open(4, 'რა არის Internet printing?', `ბეჭდვა **ინტერნეტით / HTTP-ით** — Internet Printing Protocol (IPP)-ის საშუალებით.
მომხმარებელი პრინტერს უკავშირდება ბრაუზერით ან URL-ით (მაგ. http://server/printers) და ბეჭდავს დისტანციურად. Windows Server-ში ეს არის PDS-ის **Internet Printing** როლის სერვისი (მუშაობს IIS-ზე).`);
  open(4, 'რა არის local printer?', `ლოკალური პრინტერი — **პირდაპირ კომპიუტერთან შეერთებული** პრინტერი (USB კაბელით, ძველად LPT პორტით).
მასზე მხოლოდ ამ კომპიუტერიდან იბეჭდება, თუ არ გააზიარე (share).`);
  open(4, 'რა არის network printer?', `ქსელური პრინტერი — პრინტერი, რომელიც **პირდაპირ ქსელს უერთდება** (Ethernet ან Wi-Fi) და აქვს **საკუთარი IP მისამართი**.
მას ქსელის ბევრი მომხმარებელი იყენებს ერთდროულად.`);
  open(4, 'რა არის printer pooling?', `Printer pooling — **ორი ან მეტი იდენტური** (ერთი დრაივერის მქონე) **ფიზიკური პრინტერის გაერთიანება ერთ ლოგიკურ პრინტერად**.
ბეჭდვის დავალება ავტომატურად მიდის იმ პრინტერზე, რომელიც თავისუფალია — ასე ნაწილდება დატვირთვა და ბეჭდვა უფრო სწრაფია.`);
  open(4, 'რა არის web printing?', `ვებ-ბეჭდვა — პრინტერებთან მუშაობა **ვებ-ბრაუზერის საშუალებით** (Internet Printing-ის ბაზაზე).
მომხმარებელი ხსნის ვებ-გვერდს (http://სერვერი/printers), ხედავს პრინტერების სიას, უერთდება პრინტერს, ბეჭდავს და მართავს ბეჭდვის რიგს — დამატებითი პროგრამის გარეშე.`);
  open(4, 'რა არის მომხმარებელთა უფლებები (User Rights)?', `User Rights — უფლებები, რომლებიც განსაზღვრავს, **რა სისტემური მოქმედებების** შესრულება შეუძლია მომხმარებელს ან ჯგუფს კომპიუტერზე.
მაგალითები: ლოკალურად შესვლა (Log on locally), სისტემის დროის შეცვლა, სისტემის გამორთვა, ბექაპის გაკეთება, Remote Desktop-ით შესვლა.
კონფიგურირდება: Local Security Policy / Group Policy → **User Rights Assignment**.
(განსხვავება: Permissions ეხება კონკრეტულ ობიექტს — ფაილს, საქაღალდეს, პრინტერს.)`);
  open(4, 'რას გულისხმობს NTFS წვდომები (NTFS permissions)?', `NTFS ნებართვები აკონტროლებს წვდომას **ფაილებსა და საქაღალდეებზე NTFS დისკზე** — მოქმედებს როგორც ლოკალურად, ისე ქსელით შესვლისას.
სტანდარტული ნებართვები: **Full Control, Modify, Read & Execute, List Folder Contents, Read, Write**.
- თითოეული შეიძლება იყოს **Allow** ან **Deny** (Deny სჭარბობს)
- ქვესაქაღალდეები ნებართვებს **მემკვიდრეობით** იღებენ (inheritance)`);
  open(4, 'რა არის დაშეარების (გაზიარების) ნებართვები (Share permissions)?', `Share permissions მოქმედებს **მხოლოდ მაშინ, როცა გაზიარებულ საქაღალდეს ქსელით** უკავშირდები (ლოკალურად არ მოქმედებს).
სამი სახისაა: **Read, Change, Full Control**.
როცა Share და NTFS ნებართვები ერთად მოქმედებს, საბოლოო (ეფექტური) წვდომა არის **ყველაზე მკაცრი** მათ შორის.`);
  open(4, 'რა წვდომის (ნებართვის) ტიპები არსებობს?', `- **წყაროს მიხედვით:** NTFS ნებართვები (ლოკალური + ქსელური) და Share ნებართვები (მხოლოდ ქსელური)
- **Allow და Deny** — ნებართვა ან აკრძალვა (Deny სჭარბობს)
- **Explicit და Inherited** — პირდაპირ მინიჭებული ან მშობელი საქაღალდიდან მემკვიდრეობით მიღებული
- **Standard და Special (Advanced)** — სტანდარტული (Full Control, Modify, Read & Execute, List Folder Contents, Read, Write) და დეტალური სპეციალური ნებართვები`);
  open(4, 'რამდენი ტიპისაა დაშეარების (გაზიარების) ნებართვები?', `**სამი ტიპის:**
- **Read** — ფაილების ნახვა და გახსნა
- **Change** — Read + ფაილების შექმნა, შეცვლა, წაშლა
- **Full Control** — Change + ნებართვების შეცვლა`);

  def(4, 'Print Server', 'სერვერი, რომელიც ქსელში ცენტრალიზებულად მართავს პრინტერებს და ბეჭდვის დავალებებს (რიგები, დრაივერები, ნებართვები). Windows-ში ამას აკეთებს Print and Document Services როლი.');
  def(4, 'Network Printing', 'ბეჭდვა ქსელის საშუალებით — ბევრი მომხმარებელი ბეჭდავს საერთო (გაზიარებულ ან ქსელურ) პრინტერზე.');
  def(4, 'Print Driver', 'პროგრამა, რომელიც ოპერაციულ სისტემასა და პრინტერს შორის „მთარგმნელია" — დოკუმენტს გარდაქმნის პრინტერისთვის გასაგებ ბრძანებებად.');
  // SMTP — უკვე არის ქვიზ 3-ში (დუბლიკატი; იხ. ქვემოთ quizzes: [3, 4])
  def(4, 'App-V', 'Application Virtualization — Microsoft-ის ტექნოლოგია, რომლითაც აპლიკაცია იზოლირებულ (ვირტუალურ) გარემოში მუშაობს, კომპიუტერზე ჩვეულებრივი ინსტალაციის გარეშე, სხვა პროგრამებთან კონფლიქტის გარეშე.');
  def(4, 'MDOP', 'Microsoft Desktop Optimization Pack — Microsoft-ის ინსტრუმენტების ნაკრები დესკტოპების მართვისა და ვირტუალიზაციისთვის (App-V, UE-V, MBAM, DaRT, AGPM).');
  def(4, 'PDS', 'Print and Document Services — Windows Server-ის როლი, რომლითაც სერვერი ხდება პრინტ სერვერი; შეიცავს Print Server, Internet Printing, LPD Service და Distributed Scan Server სერვისებს.');
  def(4, 'LPD', 'Line Printer Daemon — სერვისი (სერვერის მხარე), რომელიც UNIX/Linux კომპიუტერებიდან LPR-ით გამოგზავნილ ბეჭდვის დავალებებს იღებს Windows პრინტ სერვერზე. პორტი 515.');
  def(4, 'LPR', 'Line Printer Remote — კლიენტის მხარის პროტოკოლი/ბრძანება, რომლითაც ბეჭდვის დავალება LPD სერვერზე იგზავნება (ძირითადად UNIX/Linux-დან).');

  mcq(4, 'რა განსხვავებაა ტერმინებს „Print Device" (საბეჭდი მოწყობილობა) და „Printer" (პრინტერი) შორის Microsoft Windows-ის ტერმინოლოგიაში?', ['„Print Device" არის პროგრამული წარმოდგენა, ხოლო „Printer" — ფიზიკური აპარატურა', '„Print Device" არის ფიზიკური საბეჭდი აპარატურა, ხოლო „Printer" — მისი პროგრამული წარმოდგენა ოპერაციულ სისტემაში', 'ორივე ტერმინი აბსოლუტურად იდენტურია', '„Print Device" გამოიყენება მხოლოდ ქსელური პრინტერებისთვის, ხოლო „Printer" — USB პრინტერებისთვის'], 1);
  mcq(4, 'რომელი სერვერული როლი უნდა დაინსტალირდეს Windows Server 2019-ში Print Management კონსოლისა და ცენტრალიზებული ბეჭდვის სერვისების მისაღებად?', ['File and Storage Services', 'Remote Access', 'Print and Document Services (PDS)', 'Active Directory Rights Management Services'], 2);
  mcq(4, 'რა ჰქვია Windows-ის სისტემურ სერვისს, რომელიც ბეჭდვის დავალებებს იღებს, C:\\Windows\\System32\\spool\\PRINTERS საქაღალდეში დროებით ინახავს (Spooling) და საბეჭდ მოწყობილობაზე გზავნის?', ['Print Management Service', 'Print Spooler', 'Line Printer Daemon (LPD)', 'Document Router Service'], 1);
  mcq(4, 'რა არის პრინტერების პულინგის (Printer Pooling) ძირითადი დანიშნულება?', ['ერთი ფიზიკური პრინტერის დაყოფა რამდენიმე ვირტუალურ პრინტერად', 'ორი ან მეტი იდენტური ფიზიკური საბეჭდი მოწყობილობის გაერთიანება ერთ ლოგიკურ პრინტერში დატვირთვის გადანაწილებისთვის', 'პრინტერის დრაივერების ავტომატური განახლება ინტერნეტიდან', 'ბეჭდვის დავალებების დაშიფვრა SSL/TLS სერტიფიკატებით'], 1);
  mcq(4, 'რა ჰქვია პრინტ სერვერზე არსებულ ფარულ გაზიარებულ საქაღალდეს (Hidden Share), საიდანაც კლიენტური კომპიუტერები ავტომატურად იწერენ პრინტერის დრაივერებს?', ['SPOOL$', 'DRIVERS$', 'PRINT$', 'PRINTERS$'], 2);
  mcq(4, 'რომელი პროტოკოლები გამოიყენება Windows Server 2019 პრინტ სერვერიდან პრინტერების გაზიარებისთვის?', ['მხოლოდ HTTP და HTTPS', 'SMB, IPP (Internet Printing Protocol) და LPD (Line Printer Daemon)', 'FTP, SFTP და TFTP', 'მხოლოდ RDP და ICA'], 1);
  mcq(4, 'რას უზრუნველყოფს Branch Office Direct Printing (BODP) ფუნქცია?', ['ფილიალის კლიენტების ბეჭდვის დავალებები პირდაპირ გადაეცემა ფილიალში არსებულ ქსელურ პრინტერს, ცენტრალური პრინტ სერვერის გვერდის ავლით (ტრაფიკის დაზოგვის მიზნით)', 'ავტომატურად ყიდულობს ქაღალდს და ტონერს დისტანციური ოფისებისთვის', 'კრძალავს ფილიალებიდან ბეჭდვას სამუშაო საათების შემდეგ', 'ბეჭდავს მხოლოდ PDF ფორმატის დოკუმენტებს'], 0);
